"""Confined, strict local JSON-LD profile; no network, services or implicit writes."""
from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path, PurePosixPath
import copy
import hashlib
import json
import os
import re
import stat
import tempfile
import fcntl
from contextlib import contextmanager

VERSION = "1.0.0"
CORE = "urn:sys4ai:ontology:core:"
PROJECT = "urn:sys4ai:ontology:project:"
CONTEXT_PATH = "ONTOLOGY/contexts/context-v1.jsonld"
COMMON_KEYS = {"@id", "@type", "kind", "label", "definition", "lifecycle", "module", "sources", "fact_kind", "aliases", "scope_note", "examples", "non_examples", "ambiguity_with", "deprecation_reason", "replacement", "history"}
KIND_KEYS = {"concept": set(), "instance": set(), "predicate": {"domain", "range", "acyclic", "cardinality", "qualifiers"}, "relation": {"subject", "predicate", "object", "qualifiers"}, "binding": {"entity", "binding_type"}}
RECORD_KEYS = sorted(COMMON_KEYS | set().union(*KIND_KEYS.values()))
TRUSTED_CONTEXT = {"@context": {"@version": 1.1, **{k: CORE + "field:" + k for k in RECORD_KEYS if not k.startswith("@")} }}
DIGEST_RE = re.compile(r"[0-9a-f]{64}\Z")
IDENTITY_RE = re.compile(r"[a-z0-9][a-z0-9-]{0,79}\Z")
ID_RE = re.compile(r"urn:sys4ai:ontology:(?:core:|project:[a-z0-9][a-z0-9-]{0,79}:)[A-Za-z0-9][A-Za-z0-9._:-]{0,159}\Z")


class OntologyError(ValueError):
    def __init__(self, code, message, *, path=None, record_id=None):
        super().__init__(message)
        self.code, self.message, self.path, self.record_id = code, str(message)[:1000], path, record_id

    def as_dict(self):
        return {"code": self.code, "message": self.message, "path": self.path, "record_id": self.record_id, "severity": "error"}


def require(condition, code, message, **location):
    if not condition:
        raise OntologyError(code, message, **location)


def exact(value, required, optional=(), *, path=None):
    require(isinstance(value, dict), "invalid_object", "Expected an object.", path=path)
    require(set(required) <= set(value) <= set(required) | set(optional), "unsupported_fields", "Missing required fields or unsupported profile fields: " + ", ".join(sorted((set(required)-set(value)) | (set(value)-set(required)-set(optional)))), path=path)


def canonical_bytes(value):
    return (json.dumps(value, sort_keys=True, ensure_ascii=False, indent=2, allow_nan=False) + "\n").encode("utf-8")


def sha256(value):
    if isinstance(value, Path):
        value = read_bytes(value)
    return hashlib.sha256(value).hexdigest()


def relative_path(value):
    require(isinstance(value, str) and value and "\\" not in value and "\x00" not in value, "unsafe_path", "Expected a nonempty relative POSIX path.")
    p = PurePosixPath(value)
    require(not p.is_absolute() and all(x not in {"", ".", ".."} for x in value.split("/")) and not any(ord(c)<32 for c in value), "unsafe_path", "Absolute, traversal, empty and control-character paths are forbidden.", path=value)
    return p


def safe_path(root, relative, *, must_exist=True):
    root = Path(root)
    rel = relative_path(relative)
    candidate = root
    for component in rel.parts:
        candidate /= component
        require(not candidate.is_symlink(), "unsafe_symlink", "Symlink components are forbidden.", path=relative)
    require(candidate.resolve(strict=False).is_relative_to(root.resolve(strict=True)), "unsafe_path", "Path escaped selected project root.", path=relative)
    if must_exist:
        require(candidate.exists(), "missing_file", "Selected file or directory is absent.", path=relative)
    return candidate


def read_bytes(path, *, max_bytes=2_000_000):
    path = Path(path)
    try:
        parent = directory_fd(path.absolute().parent)
        try:
            fd = os.open(path.name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=parent)
        finally:
            os.close(parent)
        with os.fdopen(fd, "rb") as stream:
            st = os.fstat(stream.fileno())
            require(stat.S_ISREG(st.st_mode) and st.st_nlink == 1, "unsafe_file", "Expected a regular file without hardlink aliases.", path=str(path))
            require(st.st_size <= max_bytes, "input_too_large", "Selected file exceeds the bounded input size.", path=str(path))
            data = stream.read(max_bytes + 1)
            require(len(data) <= max_bytes, "input_too_large", "Selected file exceeds the bounded input size.", path=str(path))
            return data
    except OSError as exc:
        raise OntologyError("unavailable_file", "Cannot read selected regular file.", path=str(path)) from exc


def directory_fd(path, *, create=False):
    """Open every directory without following symlinks; caller owns the returned fd."""
    p = Path(path).absolute()
    fd = os.open("/", os.O_RDONLY | os.O_DIRECTORY)
    try:
        for part in p.parts[1:]:
            if create:
                try: os.mkdir(part, mode=0o755, dir_fd=fd)
                except FileExistsError: pass
            next_fd = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
            os.close(fd); fd = next_fd
        return fd
    except BaseException:
        os.close(fd); raise


def atomic_write(root, relative, data, expected):
    """Expected-byte replacement in a confined opened directory, followed by fsync."""
    path = safe_path(root, relative, must_exist=False)
    fd = directory_fd(path.parent, create=True)
    temporary = ".ontology-" + os.urandom(12).hex()
    try:
        actual = sha256(read_bytes(path)) if path.exists() else None
        require(actual == expected, "write_conflict", "Destination changed before replacement.", path=relative)
        out = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600, dir_fd=fd)
        with os.fdopen(out, "wb") as stream:
            stream.write(data); stream.flush(); os.fsync(stream.fileno())
        actual = sha256(read_bytes(path)) if path.exists() else None
        require(actual == expected, "write_conflict", "Destination changed at replacement boundary.", path=relative)
        require(os.fstat(fd).st_ino == os.stat(path.parent, follow_symlinks=False).st_ino, "write_conflict", "Destination directory identity changed.", path=relative)
        safe_path(root, relative, must_exist=False)
        os.replace(temporary, path.name, src_dir_fd=fd, dst_dir_fd=fd)
        os.fsync(fd)
        require(sha256(read_bytes(path)) == sha256(data), "write_conflict", "Written destination differs from accepted content.", path=relative)
    finally:
        try: os.unlink(temporary, dir_fd=fd)
        except FileNotFoundError: pass
        os.close(fd)


@contextmanager
def operation_lock(root, relative):
    path = safe_path(root, relative, must_exist=False)
    parent = directory_fd(path.parent, create=True)
    fd = None
    try:
        fd = os.open(path.name, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW | os.O_NONBLOCK, 0o600, dir_fd=parent)
        st = os.fstat(fd)
        require(stat.S_ISREG(st.st_mode) and st.st_nlink == 1, "unsafe_lock", "Lock path must be an unaliased regular file.")
        try: fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as exc: raise OntologyError("operation_locked", "A potentially active writer holds the ontology lock.") from exc
        yield
    finally:
        if fd is not None: os.close(fd)
        os.close(parent)


def decode_json(data, *, path=None):
    def pairs(items):
        result = {}
        for key, value in items:
            require(key not in result, "duplicate_json_key", "Duplicate JSON key: " + key, path=path)
            result[key] = value
        return result
    try:
        return json.loads(data.decode("utf-8"), object_pairs_hook=pairs, parse_constant=lambda value: (_ for _ in ()).throw(OntologyError("invalid_json", "Non-finite JSON numbers are forbidden.", path=path)))
    except (UnicodeError, json.JSONDecodeError, RecursionError) as exc:
        raise OntologyError("invalid_json", "Expected strict UTF-8 JSON; YAML features are unsupported.", path=path) from exc


def read_json(path):
    return decode_json(read_bytes(path), path=str(path))


def digest(value):
    require(isinstance(value, str) and DIGEST_RE.fullmatch(value), "invalid_digest", "Expected lowercase SHA256 hex.")


def allowed_source_path(path):
    parts = relative_path(path).parts
    folded = tuple(p.casefold() for p in parts)
    forbidden_roots = {"projects", "electronics", "memory", "tasks", "control_records"}
    forbidden = {"node_modules", "__pycache__", ".git", ".sys4ai", ".venv", ".ssh", ".aws", "cache", "caches"}
    require(folded[0] not in forbidden_roots and not any(p in forbidden or p.startswith(".venv") for p in folded), "source_forbidden", "Private runtime, child projects, Tasks and memory are not ontology source bindings.", path=path)
    require(not any(p.startswith(".") for p in parts) or parts[:2] == (".agents", "skills"), "source_forbidden", "Hidden source paths are not permitted.", path=path)
    require(not re.search(r"(?:^|[._-])(secret|secrets|credential|credentials|password|token|env)(?:$|[._-])", "/".join(parts).lower()), "source_forbidden", "Sensitive source names are excluded.", path=path)
    require(not path.casefold().startswith("ontology/wiki/"), "source_forbidden", "Generated wiki content is not a canonical source.", path=path)


def parse_document(data, context_path, location):
    value = decode_json(data, path=location)
    exact(value, ("@context", "@graph"), path=location)
    require(value["@context"] == context_path, "untrusted_context", "Only the configured trusted local context is supported; remote or nested contexts are forbidden.", path=location)
    require(isinstance(value["@graph"], list) and len(value["@graph"]) <= 10000, "invalid_graph", "Expected a bounded graph array.", path=location)
    result = []
    for index, record in enumerate(value["@graph"]):
        where = f"{location}#/@graph/{index}"
        require(isinstance(record, dict), "invalid_record", "Graph entries must be objects.", path=where)
        kind = record.get("kind")
        require(isinstance(kind, str) and kind in KIND_KEYS, "unsupported_kind", "Unsupported record kind.", path=where)
        require(set(record) <= COMMON_KEYS | KIND_KEYS[kind], "unsupported_profile", "Unsupported JSON-LD or record property.", path=where, record_id=record.get("@id"))
        require(isinstance(record.get("@id"), str) and ID_RE.fullmatch(record["@id"]), "invalid_id", "Expected a stable project-separated ontology URN.", path=where)
        for key in ("label", "definition", "lifecycle", "module", "fact_kind", "scope_note", "deprecation_reason", "replacement", "subject", "predicate", "object", "entity", "binding_type"):
            if key in record:
                require(isinstance(record[key], str), "invalid_metadata", key + " must be a string.", path=where, record_id=record["@id"])
        for key in ("@type", "aliases", "examples", "non_examples", "ambiguity_with", "domain", "range"):
            if key in record:
                require(isinstance(record[key], list) and all(isinstance(v, str) for v in record[key]), "invalid_metadata", key + " must be a string array.", path=where, record_id=record["@id"])
        result.append((record, where))
    return result


def load_config(root, expected_project_id=None):
    return _validate_config(root, read_json(safe_path(root, "ontology.yaml")), expected_project_id)


def _validate_config(root, cfg, expected_project_id=None):
    """Data-only candidate validation; ordinary load overrides retain their scope."""
    exact(cfg, ("schema_version", "project", "context", "modules", "project_files", "binding_files", "source_allowlist", "retrieval", "publication"), ("competency_files",))
    require(type(cfg["schema_version"]) is int and cfg["schema_version"] == 1, "unsupported_schema", "Unsupported ontology configuration schema.")
    p = cfg["project"]
    exact(p, ("id", "name", "purpose", "namespace", "root"))
    require(isinstance(p["id"], str) and IDENTITY_RE.fullmatch(p["id"]) and all(isinstance(p[x], str) and p[x].strip() for x in ("name", "purpose")), "unresolved_identity", "Specialize the neutral project identity, name and purpose before use.")
    require(p["root"] == "." and p["namespace"] == PROJECT+p["id"]+":", "identity_mismatch", "Project root or namespace does not match its selected identity.")
    require(expected_project_id is None or expected_project_id == p["id"], "identity_mismatch", "Caller selected a different project identity.")
    identity = safe_path(root, "project.json", must_exist=False)
    if identity.exists():
        saved = read_json(identity)
        require(saved.get("project_id") == p["id"] and saved.get("project_name") == p["name"] and saved.get("purpose") == p["purpose"], "identity_mismatch", "Ontology identity differs from project.json.")
    registry = safe_path(root, "depot/projects.json", must_exist=False)
    if registry.exists():
        own = [r for r in read_json(registry).get("projects", []) if r.get("path") == "."]
        require(len(own) == 1 and own[0].get("id") == p["id"], "identity_mismatch", "Ontology identity differs from the local registry root.")
    exact(cfg["context"], ("path", "sha256"))
    require(cfg["context"]["path"] == CONTEXT_PATH, "untrusted_context", "Only the versioned local profile context path is supported.")
    digest(cfg["context"]["sha256"])
    context_file = safe_path(root, CONTEXT_PATH)
    require(sha256(context_file) == cfg["context"]["sha256"] and read_json(context_file) == TRUSTED_CONTEXT, "untrusted_context", "Trusted context content or digest differs from the supported profile.")
    for key in ("modules", "project_files", "binding_files", "source_allowlist"):
        require(isinstance(cfg[key], list), "invalid_config", f"{key} must be an array.")
    for key, prefix in (("project_files", "ONTOLOGY/modules/project/"), ("binding_files", "ONTOLOGY/bindings/")):
        require(cfg[key] and all(isinstance(p, str) for p in cfg[key]) and len(cfg[key]) == len(set(cfg[key])), "invalid_config", f"{key} must select distinct file paths.")
        for path in cfg[key]:
            relative_path(path)
            endings = (".jsonld", ".json") if key == "binding_files" else (".jsonld",)
            require(path.startswith(prefix) and path.endswith(endings), "canonical_scope", "Canonical file lies outside its selected scope.", path=path)
    require(all(isinstance(p, str) for p in cfg["source_allowlist"]) and len(cfg["source_allowlist"]) == len(set(cfg["source_allowlist"])), "invalid_config", "Source allowlist must contain distinct file paths.")
    for path in cfg["source_allowlist"]:
        allowed_source_path(path)
        safe_path(root, path, must_exist=False)
    require(isinstance(cfg.get("competency_files", []), list), "invalid_config", "competency_files must be an array.")
    for path in cfg.get("competency_files", []):
        relative_path(path)
        require(path.startswith("ONTOLOGY/modules/project/") and path.endswith(".json"), "canonical_scope", "Project competency files must be explicit local JSON files.")
    exact(cfg["retrieval"], ("default_hops", "max_hops", "default_limit", "max_limit", "max_context_bytes"))
    r = cfg["retrieval"]
    require(all(type(v) is int for v in r.values()) and 0 <= r["default_hops"] <= r["max_hops"] <= 8 and 1 <= r["default_limit"] <= r["max_limit"] <= 100 and 1024 <= r["max_context_bytes"] <= 32000, "invalid_limits", "Retrieval settings exceed the release bounds.")
    exact(cfg["publication"], ("enabled", "binding"))
    require(type(cfg["publication"]["enabled"]) is bool, "invalid_publication", "Publication enabled must be boolean.")
    binding = cfg["publication"]["binding"]
    if binding is not None:
        exact(binding, ("actor_id", "scope", "authority"))
        require(isinstance(binding["actor_id"], str) and binding["actor_id"] and isinstance(binding["scope"], list), "invalid_publication", "Expected destination-local Director and explicit scope.")
        require(binding["scope"] and all(isinstance(p, str) for p in binding["scope"]) and set(binding["scope"]) <= {"ONTOLOGY/modules/project", "ONTOLOGY/bindings"}, "invalid_publication", "Publication binding exceeds canonical project scope.")
        require(isinstance(binding["authority"], list) and all(isinstance(v, dict) and isinstance(v.get("path"), str) for v in binding["authority"]) and {v.get("path") for v in binding["authority"]} == {"SOUL.md", "AGENTS.md", "ROLE.md"} and len(binding["authority"]) == 3, "invalid_publication", "Bind exactly the current governing source trio.")
        for ref in binding["authority"]:
            exact(ref, ("path", "sha256")); digest(ref["sha256"])
    require(not cfg["publication"]["enabled"] or binding is not None, "invalid_publication", "Enabled publication requires destination-local authority.")
    return cfg


@dataclass
class Project:
    root: Path
    config: dict
    records: list
    by_id: dict
    relations: list
    modules: list
    locations: dict
    sources: list = field(default_factory=list)
    diagnostics: list = field(default_factory=list)
    snapshot: dict = field(default_factory=dict)

    @property
    def project_id(self):
        return self.config["project"]["id"]

    @property
    def namespace(self):
        return self.config["project"]["namespace"]

    def context(self):
        result = copy.deepcopy(self.snapshot)
        result["snapshot_sha256"] = sha256(canonical_bytes(self.snapshot))
        return result


def check_locator(data, locator):
    require(isinstance(locator, str) and 0 < len(locator) <= 300, "invalid_locator", "Expected a bounded useful source locator.")
    if locator.startswith("section:"):
        require(locator[8:].strip() and locator[8:].strip() in data.decode("utf-8"), "invalid_locator", "Source section is absent.")
    elif re.fullmatch(r"lines?:[1-9][0-9]*(?:-[1-9][0-9]*)?", locator):
        bounds = [int(x) for x in locator.split(":")[1].split("-")]
        require(1 <= bounds[0] <= bounds[-1] <= len(data.decode("utf-8").splitlines()), "invalid_locator", "Source line locator is outside the selected file.")
    elif locator.startswith("json:"):
        value = decode_json(data)
        try:
            for part in locator[5:].strip("/").split("/") if locator[5:].strip("/") else []:
                part = part.replace("~1", "/").replace("~0", "~")
                value = value[int(part)] if isinstance(value, list) else value[part]
        except (KeyError, IndexError, TypeError, ValueError) as exc:
            raise OntologyError("invalid_locator", "Source JSON pointer is absent.") from exc
    else:
        raise OntologyError("invalid_locator", "Supported locators are section:, line:/lines:, and json:.")


def source_status(project, source):
    exact(source, ("path", "sha256", "locator"))
    digest(source["sha256"]); allowed_source_path(source["path"])
    require(isinstance(source["locator"], str) and 0 < len(source["locator"]) <= 300 and source["locator"].startswith(("section:", "line:", "lines:", "json:")), "invalid_locator", "Expected an exact supported source locator.", path=source["path"])
    permitted = set(project.config["source_allowlist"])
    for module in project.modules:
        permitted.update(module["path"] + "/" + name for name in module["files"])
    require(source["path"] in permitted, "source_unselected", "Source is not an explicitly selected file.", path=source["path"])
    path = safe_path(project.root, source["path"], must_exist=False)
    result = {**source, "status": "unavailable", "actual_sha256": None, "diagnostic": None}
    try:
        data = read_bytes(path)
        result["actual_sha256"] = sha256(data)
        result["status"] = "current" if result["actual_sha256"] == source["sha256"] else "stale"
        if result["status"] == "current":
            check_locator(data, source["locator"])
        else:
            result["diagnostic"] = "Source bytes differ from the recorded version."
    except OntologyError as exc:
        if exc.code == "invalid_locator":
            raise
        result["diagnostic"] = "Selected source is missing or inaccessible."
    return result


def load_project(root, *, expected_project_id=None, validate=True, _overrides=None):
    return _load_project(root, expected_project_id=expected_project_id, validate=validate, overrides=_overrides)


def _load_project(root, *, expected_project_id=None, validate=True, overrides=None, config=None):
    selected = Path(root).absolute()
    require(selected.is_dir() and not selected.is_symlink(), "invalid_root", "Select an existing explicit project directory.")
    require(selected.resolve() == selected, "unsafe_root", "Project root must be resolved without symlink aliases.")
    cfg = load_config(selected, expected_project_id) if config is None else _validate_config(selected, config, expected_project_id)
    overrides = overrides or {}
    require(set(overrides) <= set(cfg["project_files"] + cfg["binding_files"] + cfg.get("competency_files", [])), "canonical_scope", "Preview override lies outside selected canonical files.")
    from ontology_modules import load_modules
    records, modules, locations, inputs = load_modules(selected, cfg)
    inputs.update({"ontology.yaml": sha256(selected / "ontology.yaml") if config is None else sha256(canonical_bytes(config)), CONTEXT_PATH: cfg["context"]["sha256"]})
    for path in cfg.get("competency_files", []):
        competency = safe_path(selected, path, must_exist=path not in overrides)
        data = overrides[path] if path in overrides else read_bytes(competency)
        decode_json(data)
        inputs[path] = sha256(data)
    for identity_path in ("project.json", "depot/projects.json"):
        p = safe_path(selected, identity_path, must_exist=False)
        if p.exists(): inputs[identity_path] = sha256(p)
    for path in cfg["project_files"] + cfg["binding_files"]:
        data = overrides[path] if path in overrides else read_bytes(safe_path(selected, path))
        inputs[path] = sha256(data)
        for record, location in parse_document(data, CONTEXT_PATH, path):
            require(record["@id"].startswith(cfg["project"]["namespace"]), "core_redefinition", "Project records cannot redefine core or other-project identities.", path=location, record_id=record["@id"])
            require(record.get("module") == "project", "module_ownership", "Project records must belong to the project module.", path=location, record_id=record["@id"])
            require(record["@id"] not in locations, "duplicate_id", "Duplicate ontology identity.", path=location, record_id=record["@id"])
            if path in cfg["binding_files"]:
                require(record["kind"] == "binding", "binding_scope", "Only bindings belong in binding files.", path=location)
            else:
                require(record["kind"] != "binding", "binding_scope", "Bindings belong in explicit binding files.", path=location)
            records.append(record); locations[record["@id"]] = location
    records.sort(key=lambda record: record["@id"])
    project = Project(selected, cfg, records, {r["@id"]: r for r in records}, [r for r in records if r["kind"] == "relation"], modules, locations)
    seen = set()
    for record in records:
        sources = record.get("sources", [])
        require(isinstance(sources, list), "invalid_sources", "Sources must be an array.", path=locations[record["@id"]], record_id=record["@id"])
        for source in sources:
            key = canonical_bytes(source)
            if key not in seen:
                project.sources.append(source_status(project, source)); seen.add(key)
    project.sources.sort(key=lambda x: (x["path"], x["sha256"], x["locator"]))
    for source in project.sources:
        inputs[source["path"]] = source["actual_sha256"]
        if source["status"] != "current":
            project.diagnostics.append({"code": "source_" + source["status"], "message": source["diagnostic"], "path": source["path"], "record_id": None, "severity": "warning"})
    helpers = {p.name: sha256(p) for p in sorted(Path(__file__).parent.glob("ontology*.py")) if not p.is_symlink()}
    project.snapshot = {"project_id": project.project_id, "profile_version": VERSION, "generator_version": VERSION, "inputs": dict(sorted(inputs.items())), "modules": [{k: m[k] for k in ("id", "version", "path", "sha256", "manifest_sha256")} for m in modules], "sources": copy.deepcopy(project.sources), "helpers": helpers}
    from ontology_validate import validate_records
    findings = validate_records(project)
    project.diagnostics.extend(findings)
    project.diagnostics.sort(key=lambda d: (d["code"], d.get("record_id") or "", d.get("path") or ""))
    if validate and any(d["severity"] == "error" for d in findings):
        d = next(d for d in findings if d["severity"] == "error")
        raise OntologyError(d["code"], d["message"], path=d["path"], record_id=d["record_id"])
    return project


def assert_current(project):
    require(not any(s["status"] != "current" for s in project.sources), "source_not_current", "Explicit builds/publication require current selected source bytes.")
    for path, expected in project.snapshot["inputs"].items():
        p = safe_path(project.root, path, must_exist=False)
        actual = sha256(p) if p.exists() else None
        require(actual == expected, "input_changed", "Selected input changed after loading.", path=path)
    helpers = {p.name: sha256(p) for p in sorted(Path(__file__).parent.glob("ontology*.py")) if not p.is_symlink()}
    require(helpers == project.snapshot["helpers"], "helper_changed", "Ontology helper files changed after loading.")

"""Exact reviewed canonical publication with immutable accepted intents and receipts."""
from pathlib import Path
import copy
import re
from ontology_core import (OntologyError, load_project, canonical_bytes, sha256, safe_path, read_json,
                           read_bytes, decode_json, require, exact, digest, atomic_write, operation_lock)
from ontology_validate import validate_project
from ontology_lifecycle import validate_transition
from ontology_authority import authorize

CONTROL = "control_records/ontology/"
ONTOLOGY_GUARDED_ACTIONS = ["preview", "publish", "recover", "integration_preview", "integration_publish", "integration_recover"]


def _guard(root, operation, arguments, targets):
    from ontology_guards import begin_action, require_adapter, GuardError
    try:
        decision = begin_action(root, "ontology", operation, arguments, targets)
        require_adapter(decision, __file__)
        return decision
    except GuardError as exc:
        raise OntologyError(exc.code, str(exc)) from exc


def _recheck(decision, *, targets=True):
    from ontology_guards import GuardError
    try:
        decision.recheck(targets=targets)
        if targets and decision.operation != "preview":
            decision.lock_checked = True
    except GuardError as exc:
        raise OntologyError(exc.code, str(exc)) from exc


def _root(value):
    path = Path(value).absolute()
    require(path.is_dir() and not path.is_symlink() and path == path.resolve(), "unsafe_root", "Select an existing resolved project root without symlink aliases.")
    return path


def check_proposal(root, proposal):
    exact(proposal, ("schema_version", "operation_id", "operation", "reason", "changes"))
    require(type(proposal["schema_version"]) is int and proposal["schema_version"] in {1, 2} and proposal["operation"] == "publish", "unsupported_operation", "Expected explicit versioned ontology publication.")
    require(isinstance(proposal["operation_id"], str) and re.fullmatch(r"ONTOP-[A-Za-z0-9-]{4,100}", proposal["operation_id"]), "invalid_operation", "Use a stable ONTOP operation identity.")
    require(isinstance(proposal["reason"], str) and 0 < len(proposal["reason"].strip()) <= 2000, "missing_reason", "Exact review requires a bounded reason.")
    require(isinstance(proposal["changes"], list) and 1 <= len(proposal["changes"]) <= 50, "invalid_changes", "Select one to fifty exact canonical files.")
    cfg = read_json(safe_path(root, "ontology.yaml"))
    permitted = set(cfg["project_files"] + cfg["binding_files"] + cfg.get("competency_files", []))
    if proposal["schema_version"] == 2:
        from ontology_advanced import load_advanced
        advanced = load_advanced(root, required=True)
        permitted.update(ref["path"] for ref in advanced["extensions"])
        permitted.add("ontology-advanced.yaml")
        for ref in advanced["extensions"]:
            permitted.update(s["path"] for s in read_json(safe_path(root, ref["path"])).get("shapes", []))
    seen = set()
    for change in proposal["changes"]:
        exact(change, ("path", "expected_sha256", "content", "sha256"))
        require(isinstance(change["path"], str) and change["path"] in permitted and change["path"] not in seen, "canonical_scope", "Change must select one distinct configured project canonical file.", path=change["path"] if isinstance(change["path"], str) else None)
        seen.add(change["path"]); safe_path(root, change["path"], must_exist=False)
        require(isinstance(change["content"], str) and len(change["content"].encode()) <= 250000, "invalid_content", "Provide exact reviewed UTF-8 content up to 250000 bytes.")
        digest(change["sha256"])
        if change["expected_sha256"] is not None: digest(change["expected_sha256"])
        require(sha256(change["content"].encode()) == change["sha256"], "content_digest", "Proposed content differs from its reviewed digest.")
        if not change["path"].endswith(".ttl"):
            decode_json(change["content"].encode(), path=change["path"])
    if proposal["schema_version"] == 2:
        overrides = {c["path"]: c["content"].encode() for c in proposal["changes"]}
        updated = load_advanced(root, required=True, _overrides=overrides)
        old_other = {k:v for k,v in advanced.items() if k != "extensions"}
        new_other = {k:v for k,v in updated.items() if k != "extensions"}
        require(old_other == new_other and [r["path"] for r in advanced["extensions"]] == [r["path"] for r in updated["extensions"]],
                "advanced_config_scope", "Semantic publication may update existing extension locks only; profiles, authority, limits and new imports use selected setup.")
        for ref in advanced["extensions"]:
            if ref["path"] in overrides:
                before = read_json(safe_path(root, ref["path"]))
                after = decode_json(overrides[ref["path"]])
                require(before["id"] == after.get("id") and before["project_id"] == after.get("project_id"), "identity_recycled", "An extension retains its stable identity and project.")
                for key in ("axioms", "annotations", "negative_assertions"):
                    old_statements = {r["id"]: r for r in before[key]}
                    new_statements = {r["id"]: r for r in after.get(key, [])}
                    require(all(new_statements.get(rid) == record for rid,record in old_statements.items()),
                            "extension_history", "Published extension statement identities and their meaning are immutable; add distinct sourced statements through review.")
                require(before.get("shapes", []) == after.get("shapes", []) or
                        [s["path"] for s in before.get("shapes", [])] == [s["path"] for s in after.get("shapes", [])],
                        "advanced_config_scope", "New shape selection requires selected setup.")
    return proposal


def _candidate(root, proposal, *, old_overrides=None):
    prior_all = dict(old_overrides or {})
    config = read_json(safe_path(root, "ontology.yaml"))
    core_paths = set(config["project_files"] + config["binding_files"] + config.get("competency_files", []))
    prior = {p:b for p,b in prior_all.items() if p in core_paths}
    for change in proposal["changes"]:
        if change["expected_sha256"] is None and change["path"] in core_paths:
            empty = {"schema_version": 1, "questions": []} if change["path"] in config.get("competency_files", []) else {"@context": config["context"]["path"], "@graph": []}
            prior[change["path"]] = canonical_bytes(empty)
    old = load_project(root, validate=False, _overrides=prior)
    for change in proposal["changes"]:
        if change["expected_sha256"] is None: old.snapshot["inputs"][change["path"]] = None
    overrides = {c["path"]: c["content"].encode() for c in proposal["changes"]}
    new = load_project(root, _overrides={p:b for p,b in overrides.items() if p in core_paths})
    if proposal["schema_version"] == 2:
        from ontology_advanced import load_advanced, load_extensions
        for project, selected in ((old, prior_all), (new, overrides)):
            advanced = load_advanced(root, required=True, _overrides=selected)
            extensions, inputs, sources = load_extensions(project, advanced, _overrides=selected)
            require(all(s["status"] == "current" for s in sources), "source_not_current", "Extensions must cite current selected source bytes.")
            inputs["ontology-advanced.yaml"] = sha256(selected.get("ontology-advanced.yaml", read_bytes(safe_path(root, "ontology-advanced.yaml"))))
            project.snapshot["inputs"].update(inputs)
            project.snapshot["advanced"] = {"config": advanced, "extensions": extensions}
    require(all(s["status"] == "current" for s in new.sources), "source_not_current", "Proposed complete graph must cite current selected sources.")
    findings = validate_transition(old.records, new.records)
    require(not findings, findings[0]["code"] if findings else "invalid_transition", findings[0]["message"] if findings else "", record_id=findings[0]["record_id"] if findings else None)
    return old, new


def _advanced_checks(root, proposal):
    if proposal["schema_version"] != 2:
        return None
    from ontology_advanced import load_advanced
    from ontology_standards import validate, infer, health
    cfg = load_advanced(root, required=True)
    require(cfg["profiles"].get("standards", {}).get("enabled"), "standards_required", "Advanced publication requires selected standards validation.")
    overrides = {c["path"]: c["content"].encode() for c in proposal["changes"]}
    checked = validate(root, overrides=overrides)
    require(checked.get("complete") is True and checked.get("conforms") is True,
            "advanced_validation_failed", "The exact advanced candidate did not complete conformant standards validation: " + str(checked.get("status")))
    if cfg["profiles"].get("inference", {}).get("enabled"):
        inferred = infer(root, overrides=overrides)
        require(inferred.get("complete") is True and inferred.get("status") == "ok" and inferred.get("trusted") is True,
                "advanced_consistency_failed", "The exact advanced candidate did not establish consistent finite reasoning: " + str(inferred.get("status")))
    return {"standards": "conformant", "inference": "consistent" if cfg["profiles"].get("inference", {}).get("enabled") else "not_applicable",
            "context": checked.get("context"), "versions": checked.get("versions"), "readiness": health(root)}


def preview(root, proposal):
    root = _root(root)
    check_proposal(root, proposal)
    decision = _guard(root, "preview", {"proposal": proposal}, [c["path"] for c in proposal["changes"]])
    for change in proposal["changes"]:
        path = safe_path(root, change["path"], must_exist=False)
        require((sha256(path) if path.exists() else None) == change["expected_sha256"], "expected_changed", "Canonical bytes changed since the proposed review.", path=change["path"])
    old, new = _candidate(root, proposal)
    advanced_validation = _advanced_checks(root, proposal)
    value = {"schema_version": 1, "operation_id": proposal["operation_id"], "payload_sha256": sha256(canonical_bytes(proposal)), "reason": proposal["reason"], "changes": [{k: c[k] for k in ("path", "expected_sha256", "sha256")} for c in proposal["changes"]], "before": old.context(), "after": new.context(), "valid": True}
    if advanced_validation is not None:
        value["advanced_validation"] = advanced_validation
    _recheck(decision)
    value = decision.finish(value)
    value["preview_sha256"] = sha256(canonical_bytes(value))
    return value


def _intent_paths(operation_id):
    require(isinstance(operation_id, str) and re.fullmatch(r"ONTOP-[A-Za-z0-9-]{4,100}", operation_id), "invalid_operation", "Expected exact ONTOP operation identity.")
    return tuple(CONTROL + kind + "/" + operation_id + ".json" for kind in ("intents", "receipts", "recovery"))


def _read_intent(root, operation_id):
    path, _, _ = _intent_paths(operation_id)
    intent = read_json(safe_path(root, path))
    exact(intent, ("schema_version", "proposal", "preview", "prior_contents", "publisher", "intent_sha256"))
    checked = dict(intent); checked.pop("intent_sha256")
    require(sha256(canonical_bytes(checked)) == intent["intent_sha256"], "intent_changed", "Accepted intent integrity differs.")
    require(intent["proposal"]["operation_id"] == operation_id, "intent_changed", "Accepted intent operation identity differs.")
    check_proposal(root, intent["proposal"])
    require(intent["preview"]["payload_sha256"] == sha256(canonical_bytes(intent["proposal"])), "intent_changed", "Accepted intent payload differs from its reviewed preview.")
    reviewed = dict(intent["preview"]); reviewed.pop("preview_sha256", None)
    require(sha256(canonical_bytes(reviewed)) == intent["preview"].get("preview_sha256"), "intent_changed", "Accepted preview no longer matches the reviewed digest.")
    for change in intent["proposal"]["changes"]:
        content = intent["prior_contents"].get(change["path"])
        require((sha256(content.encode()) if isinstance(content, str) else None) == change["expected_sha256"], "intent_changed", "Accepted prior content differs from the reviewed expected version.")
    return intent


def _advance(root, intent, grant, *, fail_at=None, decision=None):
    proposal, pre = intent["proposal"], intent["preview"]
    journal_path, receipt_path, recovery_path = _intent_paths(proposal["operation_id"])
    old, new = _candidate(root, proposal, old_overrides={p: value.encode() for p, value in intent["prior_contents"].items() if value is not None})
    advanced_validation = _advanced_checks(root, proposal)
    require(advanced_validation == pre.get("advanced_validation"), "advanced_context_changed", "Advanced rules, shapes, helpers or certified runtime changed after accepted review.")
    if decision is not None:
        _recheck(decision)
    authorize(old, grant, proposal, pre["preview_sha256"])
    changed = {c["path"] for c in proposal["changes"]}
    for relative, expected in pre["before"]["inputs"].items():
        if relative in changed: continue
        file = safe_path(root, relative, must_exist=False)
        require((sha256(file) if file.exists() else None) == expected, "recovery_input_changed", "Accepted source/configuration/module input changed.", path=relative)
    require(old.context()["helpers"] == pre["before"]["helpers"], "helper_changed", "Helper version changed after accepted review.")
    states = []
    for c in proposal["changes"]:
        path = safe_path(root, c["path"], must_exist=False)
        actual = sha256(path) if path.exists() else None
        require(actual in {c["expected_sha256"], c["sha256"]}, "recovery_conflict", "Canonical file contains unrelated edits; preserve them.", path=c["path"])
        states.append({"path": c["path"], "before_sha256": c["expected_sha256"], "sha256": c["sha256"], "state": "committed" if actual == c["sha256"] else "pending"})
    existing_receipt = safe_path(root, receipt_path, must_exist=False)
    if existing_receipt.exists():
        receipt = read_json(existing_receipt)
        require(receipt.get("intent_sha256") == intent["intent_sha256"] and all(s["state"] == "committed" for s in states), "receipt_conflict", "Completed receipt no longer agrees with actual canonical files.")
        from ontology_health import maintenance_status
        return {**receipt, "current_readiness": maintenance_status(root)}
    try:
        if fail_at == "before_commit": raise OSError("Injected pre-commit failure")
        for index, (change, state) in enumerate(zip(proposal["changes"], states)):
            if state["state"] != "committed":
                if decision is not None:
                    _recheck(decision, targets=False)
                atomic_write(root, change["path"], change["content"].encode(), change["expected_sha256"])
                state["state"] = "committed"
            if fail_at == "after_commit" or fail_at == f"after_commit:{index+1}": raise OSError("Injected post-commit failure")
        if fail_at == "projection": raise OSError("Injected projection failure")
        from ontology_build import compile_project
        projection = compile_project(root)
        receipt = {"schema_version": 1, "status": "complete", "operation_id": proposal["operation_id"], "payload_sha256": pre["payload_sha256"], "preview_sha256": pre["preview_sha256"], "intent_sha256": intent["intent_sha256"], "reason": proposal["reason"], "publisher": intent["publisher"], "files": states, "projection": projection, "context": load_project(root).context()}
        if fail_at == "receipt": raise OSError("Injected receipt failure")
        atomic_write(root, receipt_path, canonical_bytes(receipt), None)
        from ontology_health import maintenance_status
        return {**receipt, "current_readiness": maintenance_status(root)}
    except (OSError, OntologyError) as exc:
        recovery = {"schema_version": 1, "status": "partial", "operation_id": proposal["operation_id"], "intent_sha256": intent["intent_sha256"], "files": states, "error": {"code": getattr(exc, "code", "write_failure"), "message": str(exc)[:1000]}, "recovery": "Renew the current grant for the original payload/preview and recover this exact operation."}
        path = safe_path(root, recovery_path, must_exist=False)
        atomic_write(root, recovery_path, canonical_bytes(recovery), sha256(path) if path.exists() else None)
        return recovery


def publish(root, proposal, grant, *, expected_preview_sha256, fail_at=None):
    root = _root(root)
    check_proposal(root, proposal)
    decision = _guard(root, "publish", {"proposal": proposal, "grant": grant, "expected_preview_sha256": expected_preview_sha256}, [c["path"] for c in proposal["changes"]])
    journal_path, _, _ = _intent_paths(proposal["operation_id"])
    journal_file = safe_path(root, journal_path, must_exist=False)
    if journal_file.exists():
        intent = _read_intent(root, proposal["operation_id"])
        require(intent["proposal"] == proposal and intent["preview"]["preview_sha256"] == expected_preview_sha256, "operation_reused", "Operation identity cannot be reused for a different accepted change.")
        with operation_lock(root, CONTROL + "publication.lock"):
            return decision.finish(_advance(root, intent, grant, fail_at=fail_at, decision=decision))
    pre = preview(root, proposal)
    require(pre["preview_sha256"] == expected_preview_sha256, "preview_changed", "Exact reviewed preview differs from current proposed state.")
    project, _ = _candidate(root, proposal)
    authorize(project, grant, proposal, expected_preview_sha256)
    with operation_lock(root, CONTROL + "publication.lock"):
        _recheck(decision)
        require(not journal_file.exists(), "operation_race", "Another writer accepted this operation; retry its exact recorded payload.")
        pre = preview(root, proposal)
        require(pre["preview_sha256"] == expected_preview_sha256, "preview_changed", "Inputs changed while acquiring publication lock.")
        authorize(project, grant, proposal, expected_preview_sha256)
        intent = {"schema_version": 1, "proposal": copy.deepcopy(proposal), "preview": pre, "prior_contents": {c["path"]: read_bytes(safe_path(root, c["path"])).decode() if c["expected_sha256"] is not None else None for c in proposal["changes"]}, "publisher": {"actor_id": grant["actor_id"], "actor_kind": grant["actor_kind"], "grant_id": grant["grant_id"], "grant_sha256": sha256(canonical_bytes(grant)), "task": grant["task"]}}
        intent["intent_sha256"] = sha256(canonical_bytes(intent))
        require(len(canonical_bytes(intent)) <= 2_000_000, "intent_too_large", "Accepted operation exceeds bounded durable intent size.")
        if fail_at == "before_intent": raise OntologyError("injected_failure", "Injected failure before accepted intent.")
        atomic_write(root, journal_path, canonical_bytes(intent), None)
        return decision.finish(_advance(root, intent, grant, fail_at=fail_at, decision=decision))


def recover(root, operation_id, grant, *, fail_at=None):
    root = _root(root)
    intent = _read_intent(root, operation_id)
    decision = _guard(root, "recover", {"intent": intent, "grant": grant, "operation_id": operation_id}, [c["path"] for c in intent["proposal"]["changes"]])
    with operation_lock(root, CONTROL + "publication.lock"):
        require(_read_intent(root, operation_id) == intent, "intent_changed", "Accepted intent changed while acquiring recovery lock.")
        return decision.finish(_advance(root, intent, grant, fail_at=fail_at, decision=decision))


def _integration_guard(root, operation, arguments):
    from ontology_integration import TARGETS
    return _guard(root, operation, arguments, TARGETS)


def integration_preview(root, selection):
    from ontology_integration import preview
    result = preview(root, selection)
    decision = _integration_guard(root, "integration_preview", {"proposal": result["proposal"]})
    decision.recheck()
    # Guard observations are independent of the stable semantic preview digest.
    decision.finish({"valid": True})
    return result


def integration_publish(root, proposal, grant, *, expected_preview_sha256, fail_at=None):
    from ontology_integration import publish
    return publish(root, proposal, grant, expected_preview_sha256=expected_preview_sha256, fail_at=fail_at)


def integration_recover(root, operation_id, grant, *, fail_at=None):
    from ontology_integration import recover
    return recover(root, operation_id, grant, fail_at=fail_at)

"""Exact, optional semantic checks at the owning helpers' mutation boundaries.

This module grants no authority.  The public helper runs its existing authorizer
after this check.  Context variables only carry a decision down that helper's
current call stack; no reusable pass or authorization is cached.
"""
from __future__ import annotations

